  const stack = [];
  let node = root;
  let count = 0;

  while (stack.length || node) {
    while (node) {
      stack.push(node);
      node = node.left;
    }
    node = stack.pop();
    count++;
    if (count === k) return node.val;
    node = node.right;
  }

  return -1;
}

